1	import { AnimatePresence, motion } from "framer-motion";
2	import type { ReactNode } from "react";
3	
4	interface StageProps {
5	  /** changing this key cross-fades the stage content */
6	  phaseKey: string;
7	  children: ReactNode;
8	}
9	
10	/** The bordered, gradient, dot-grid game shell that cross-fades between phases
11	 *  (idle / loading / playing / result). Content is centered and responsive. */
12	export default function Stage({ phaseKey, children }: StageProps) {
13	  return (
14	    <div className="stage-shell">
15	      <div className="stage-dots" aria-hidden="true" />
16	      <div className="stage-inner">
17	        <AnimatePresence mode="wait">
18	          <motion.div
19	            key={phaseKey}
20	            initial={{ opacity: 0, y: 12 }}
21	            animate={{ opacity: 1, y: 0 }}
22	            exit={{ opacity: 0, y: -12 }}
23	            transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
24	            style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "center" }}
25	          >
26	            {children}
27	          </motion.div>
28	        </AnimatePresence>
29	      </div>
30	    </div>
31	  );
32	}
